 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    frames = []
    # Identify solid rectangular outlines (including possibly one-cell interiors).
    for color in range(1, 10):
        for r0 in range(h):
            for r1 in range(r0 + 2, h):
                for c0 in range(w):
                    for c1 in range(c0 + 2, w):
                        if all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0,c1+1)) and all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0,r1+1)):
                            if all(grid[r][c] == 0 for r in range(r0+1,r1) for c in range(c0+1,c1)):
                                frames.append((r0,r1,c0,c1,color))
    # remove duplicates, retain all outline cells; count colors of loose markers
    frame_cells = set()
    for r0,r1,c0,c1,col in frames:
        for c in range(c0,c1+1): frame_cells.add((r0,c)); frame_cells.add((r1,c))
        for r in range(r0,r1+1): frame_cells.add((r,c0)); frame_cells.add((r,c1))
    counts = Counter(grid[r][c] for r in range(h) for c in range(w) if grid[r][c] != 0 and (r,c) not in frame_cells)
    out = [[0]*w for _ in range(h)]
    for r,c in frame_cells: out[r][c] = grid[r][c]
    for r0,r1,c0,c1,col in frames:
        interior = (r1-r0-1)*(c1-c0-1)
        target_n = interior//2
        fill = next((k for k,v in counts.items() if v == target_n), None)
        if fill is not None:
            for r in range(r0+1,r1):
                for c in range(c0+1,c1):
                    if (r+c)%2 == 0: out[r][c] = fill
    return out
